from pathlib import Path
p=Path('index.html')
s=p.read_text()
old="function cards(list){if(!list.length)return `<div class=\"empty\">${esc(ct('noProductsMessage'))}</div>`;return list.map(p=>`<div class=\"product\"><div class=\"product-img\" role=\"button\" onclick=\"openProduct('${esc(p.id)}')\">${productArt(p)}</div><small>${esc(displayCategory(p.category||''))}</small><h3 role=\"button\" onclick=\"openProduct('${esc(p.id)}')\">${esc(p.name||ct('genericProductText'))}</h3><small>${esc(p.meta)}</small><div class=\"price\">${Number(p.price||0).toLocaleString()} MRU</div><div class=\"stock ${Number(p.stock||0)<=0?'out':''}\">${Number(p.stock||0)>0?'✓ '+esc(ct('availableTemplate').replace(' — {stock} في المخزون','').replace('{stock}','')):esc(ct('outOfStockText'))}</div><button class=\"add\" ${Number(p.stock||0)<=0?'disabled':''} onclick=\"addCart('${esc(p.id)}')\">${esc(ct('addCartText'))}</button></div>`).join('')}"
new="function cards(list){if(!list.length)return `<div class=\"empty\">${esc(ct('noProductsMessage'))}</div>`;return list.map(p=>`<div class=\"product\"><div class=\"product-img\" role=\"button\" onclick=\"openProduct('${esc(p.id)}')\">${productArt(p)}</div><small>${esc(displayCategory(p.category||''))}</small><h3 role=\"button\" onclick=\"openProduct('${esc(p.id)}')\">${esc(p.name||ct('genericProductText'))}</h3><small>${esc(p.meta)}</small><div class=\"price\">${Number(p.price||0).toLocaleString()} MRU</div><div class=\"stock ${Number(p.stock||0)<=0?'out':''}\">${Number(p.stock||0)>0?esc(tpl('availableTemplate',{stock:Number(p.stock||0)})):esc(ct('outOfStockText'))}</div><button class=\"add\" ${Number(p.stock||0)<=0?'disabled':''} onclick=\"addCart('${esc(p.id)}')\">${esc(ct('addCartText'))}</button></div>`).join('')}"
if old not in s: raise SystemExit('cards marker missing')
p.write_text(s.replace(old,new,1))
print('stock label fixed')
